      reset() { cam.zoom = 1; cam.x = world.w / 2; cam.y = world.h / 2; clamp(); },
      fit() { cam.zoom = Math.max(ZOOM_MIN, Math.min(vw / world.w, vh / world.h) / ZOOM_BASE); cam.x = world.w / 2; cam.y = world.h / 2; clamp(); },
